import {createCompanionIntro} from './companion-intro.js';
import {TODO_COLOURS,saveTodo,toggleTodo,deleteTodo} from './todos.js';
import {START,LEARN_END,REV_START,END,EXAM,TOPICS,STAGES,WEIGHTS,TOTAL_TASKS,createState,replan as plan,rollover as roll,toggleTask,moveTask as move,validateState,localToday,dateObj,iso,addDays,diffDays,range,weightName,topicOf,prevTask} from './planner.js';
import {refreshCommitment} from './companion.js';
import {syncCollection,collectionStatus,chooseCompanion,adoptEgg,spendCare,dailyRewardStatus,finishDailyReward,saveCareGoal,toggleCareGoal} from './collection.js';
import {companionCard,bounceCompanion,celebrateCompanion,captureRewardFill,animateRewardFill,companionsPage} from './companion-view.js';
function replan(s,d,...args){plan(s,d,...args);refreshCommitment(s,d);syncCollection(s,d);return s;}
function rollover(s,d){roll(s,d);refreshCommitment(s,d);syncCollection(s,d);return s;}
function moveTask(s,id,d,today,swap){move(s,id,d,today,swap);refreshCommitment(s,today);syncCollection(s,today);return s;}
const KEY='little-by-little.v1',UNDO=KEY+'.undo';
const demo=new URLSearchParams(location.search).get('preview')==='companions',demoStorage=new Map(),demoScenario=new URLSearchParams(location.search).get('scenario')||'grown';
const demoToday=demoScenario==='onboarding'?'2026-09-21':demoScenario==='after-exam'?'2026-10-16':'2026-09-30';
const storage={getItem:key=>demo?demoStorage.get(key):window.localStorage.getItem(key),setItem:(key,value)=>demo?demoStorage.set(key,value):window.localStorage.setItem(key,value),removeItem:key=>demo?demoStorage.delete(key):window.localStorage.removeItem(key)};
function createDemo(){
 const s=createState(START);syncCollection(s,START);
 for(const day of range(START,demoScenario==='onboarding'?'2026-09-20':demoScenario==='after-exam'?'2026-10-14':'2026-09-29')){rollover(s,day);for(const t of s.tasks.filter(t=>t.date===day&&!t.doneAt)){toggleTask(s,t.id,day);syncCollection(s,day);}finishDailyReward(s,day);}
 if(demoScenario!=='onboarding'){adoptEgg(s,'minty',demoToday);if(demoScenario!=='egg')for(let i=0;i<5;i++)spendCare(s,demoToday);}
 return s;
}

let state,storageError='',today=demo?demoToday:localToday(),page=['today','calendar','topics','companions','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'today',selected=today<START?START:today>END?END:today,month=selected.slice(0,7),activeId=null,toastTimer;
const main=document.querySelector('#main'),dialog=document.querySelector('#session-dialog');
const navigation=document.querySelector('nav'),navHighlight=document.createElement('span');
navHighlight.className='nav-highlight';navHighlight.setAttribute('aria-hidden','true');navigation.prepend(navHighlight);
const petNav=document.createElement('button');petNav.className='nav-item';petNav.dataset.page='companions';petNav.hidden=true;petNav.innerHTML='<span aria-hidden="true"><svg class="nav-icon" viewBox="0 0 24 24"><path d="M6 20c-3-2-3-6 0-8l6-5 6 5c3 2 3 6 0 8-2 1-4-1-6-1s-4 2-6 1Z"/><circle cx="5" cy="6" r="2"/><circle cx="12" cy="3.5" r="2"/><circle cx="19" cy="6" r="2"/></svg></span> Companions';navigation.querySelector('[data-page=settings]').before(petNav);
function updateNavHighlight(){
 const active=navigation.querySelector('.nav-item.active');if(!active)return;
 const parent=navigation.getBoundingClientRect(),target=active.getBoundingClientRect();
 navHighlight.style.width=target.width+'px';navHighlight.style.height=target.height+'px';
 navHighlight.style.transform=`translate(${target.left-parent.left}px,${target.top-parent.top}px)`;
 navigation.classList.add('has-highlight');
 if(!navigation.classList.contains('nav-ready'))requestAnimationFrame(()=>navigation.classList.add('nav-ready'));
}
new ResizeObserver(updateNavHighlight).observe(navigation);

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(d,opts={month:'short',day:'numeric'})=>dateObj(d).toLocaleDateString('en-AU',opts);
const longDate=d=>fmt(d,{weekday:'long',month:'long',day:'numeric'});
const getTask=id=>state.tasks.find(t=>t.id===id);
try {const saved=storage.getItem(KEY);state=saved?validateState(JSON.parse(saved)):demo?createDemo():createState(today);rollover(state,today);} catch(e){state=createState(today);storageError='Saved progress could not be loaded. Your existing data has not been overwritten; export or restore a backup from Settings.';}
function save(){syncCollection(state,today);try{if(storageError)throw Error();storage.setItem(KEY,JSON.stringify(state));}catch{storageError=storageError||'Device storage is unavailable. Keep this tab open and export a backup to keep your progress.';}updateStorageBadge();}
function updateStorageBadge(){document.querySelector('.local-badge').innerHTML=`<i></i> ${demo?'Preview · not saved':storageError?'Backup needed':'Saved on this device'}`;}
function snapshot(){try{storage.setItem(UNDO,JSON.stringify(state));}catch{}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function mutate(fn,message){const before=structuredClone(state);try{fn();try{storage.setItem(UNDO,JSON.stringify(before));}catch{}save();render();if(message)toast(message);return true;}catch(e){state=before;toast(e.message);return false;}}
function navigate(next){companionIntro.dismiss();page=next;history.replaceState(null,'','#'+next);render();window.scrollTo({top:0,behavior:'instant'});}
function header(title,subtitle,eyebrow='YOUR STUDY PLAN',pill=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${pill?`<span class="phase-pill">● &nbsp; ${pill}</span>`:''}</div>`;}
function warnings(){return (demo?`<div class="demo-banner"><span>Interactive preview · your saved plan stays untouched</span><div><a href="?preview=companions&scenario=onboarding#today">Pip’s first days</a><a href="?preview=companions&scenario=egg#companions">New egg</a><a href="?preview=companions#today">Growing companion</a><a href="?preview=companions&scenario=after-exam#today">After the exam</a><a href="./#today">Exit preview</a></div></div>`:'')+[...(storageError?[storageError]:[]),...(state.notices||[])].map(n=>`<div class="notice">${esc(n)}</div>`).join('');}
function sessionCard(t){const p=topicOf(t),prev=prevTask(state,t);const blocked=!t.doneAt&&t.stage>0&&(!prev?.doneAt||today<REV_START||diffDays(today,prev.doneAt)<(t.stage===1?1:3));return `<article class="task-card ${t.doneAt?'done':''}" ${!t.doneAt?'draggable="true"':''} data-task="${t.id}"><button class="check" data-toggle="${t.id}" aria-pressed="${!!t.doneAt}" aria-label="${t.doneAt?'Undo':'Complete'} ${esc(p.title)} ${STAGES[t.stage]}" ${blocked?'aria-disabled="true"':''}>${t.doneAt?'✓':''}</button><div class="task-copy"><div class="task-meta"><span class="subject ${p.subject.toLowerCase()}">${p.subject.toUpperCase()}</span><span>VIDEO ${String(p.number).padStart(2,'0')} · ${STAGES[t.stage].toUpperCase()}</span>${t.pinned?'<span title="Manually scheduled">⌁ MOVED</span>':''}</div><h3>${esc(p.title)}</h3>${t.rolledFrom&&!t.doneAt?`<div class="carry-label">Carried from ${fmt(t.rolledFrom)}</div>`:''}${!t.date&&!t.doneAt?'<div class="carry-label">Needs a study day</div>':''}</div><button class="more" data-session="${t.id}" aria-label="Schedule ${esc(p.title)} ${STAGES[t.stage]}">↗</button></article>`;}
function dayTasks(d){return state.tasks.filter(t=>t.date===d).sort((a,b)=>a.stage-b.stage);}
function dayTodos(d){return (state.todos||[]).filter(t=>t.date===d);}
function addTodoButton(d){return `<button class="add-todo" data-add-todo="${d}"><span aria-hidden="true">＋</span> Add to-do</button>`;}
function personalTodos(d){return dayTodos(d).map(t=>`<article class="task-card todo-card ${t.done?'done':''}" data-todo="${esc(t.id)}" style="--todo-colour:${esc(t.colour)}"><button class="check" data-todo-toggle="${esc(t.id)}" aria-pressed="${t.done}" aria-label="${t.done?'Undo':'Complete'} to-do: ${esc(t.title)}">${t.done?'✓':''}</button><div class="task-copy"><div class="task-meta"><span class="subject personal">TO-DO</span></div><h3>${esc(t.title)}</h3></div><button class="more" data-edit-todo="${esc(t.id)}" aria-label="Edit to-do: ${esc(t.title)}"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m16 3 5 5-12 12-6 1 1-6Z M13 6l5 5"/></svg></button></article>`).join('');}
function openTodo(d,id){const t=id?(state.todos||[]).find(t=>t.id===id):null;if(id&&!t)return;dialog.innerHTML=`<button class="dialog-close" data-close aria-label="Close to-do">×</button><div class="eyebrow">A LITTLE EXTRA</div><h2>${t?'Edit to-do':'A little to-do'}</h2><form id="todo-form" data-id="${esc(t?.id||'')}"><label class="field">What would you like to do?<input name="title" value="${esc(t?.title||'')}" placeholder="e.g. Go for a walk" maxlength="200" required autofocus></label><label class="field">Day<input name="date" type="date" value="${esc(t?.date||d)}" min="2026-09-18" max="2030-12-31" required></label><div class="field"><span id="todo-colour-label">Pick a colour</span><div class="todo-colours" role="group" aria-labelledby="todo-colour-label">${TODO_COLOURS.map(([label,c])=>`<button type="button" class="todo-swatch" style="--swatch:${c}" data-todo-colour="${c}" aria-label="${label}" aria-pressed="${c===(t?.colour||TODO_COLOURS[0][1])}"></button>`).join('')}<label class="custom-todo-colour"><input type="color" name="colour" value="${t?.colour||TODO_COLOURS[0][1]}" aria-label="Custom colour"><span>Custom</span></label></div></div><p>Optional extras — your study reward stays separate.</p><div class="todo-form-actions"><button class="button" type="submit">${t?'Save changes':'Add to-do'}</button>${t?`<button class="text-button todo-delete" type="button" data-delete-todo="${esc(t.id)}">Delete to-do</button>`:''}</div></form>`;dialog.showModal();}
function todayPage(){const tasks=dayTasks(today),backlog=state.tasks.filter(t=>!t.date&&!t.doneAt),done=state.tasks.filter(t=>t.doneAt).length,remaining=tasks.filter(t=>!t.doneAt).length;const phase=today<REV_START?'First pass':today<EXAM?'Spaced revision':'Exam day & beyond';const days=diffDays(EXAM,today);return header(days===0?'Exam day':'Today',dailyRewardStatus(state,today).careMode?(state.collection.careDays[today]?.done?'Your daily goal is complete.':'A small goal. A little care.'):remaining?`${remaining} session${remaining===1?'':'s'} today.`:tasks.length?'Today’s sessions are complete.':'Nothing scheduled today.',longDate(today).toUpperCase(),phase)+warnings()+`<div class="dashboard">${companionCard(state,today)}${careGoalCard()}<section><div class="progress-card"><div class="small-label">YOUR PATH TO EXAM DAY</div><div class="milestones">${['Learn','Revise'].map((label,i)=>{const doneCount=i===0?state.tasks.filter(t=>t.stage===0&&t.doneAt).length:state.tasks.filter(t=>t.stage>0&&t.doneAt).length;const total=i===0?TOPICS.length:TOPICS.length*2;const complete=doneCount===total;return `<div><span class="milestone ${complete||i===(today<REV_START?0:1)?'active':''}">${complete?'✓':i+1}</span><b>${label}</b><small>${i===0?'By Sep 26':'By Oct 14'}</small></div>`;}).join('')}</div><div class="progress-track" role="progressbar" aria-label="Total study progress" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="${TOTAL_TASKS}"><span style="width:${done/TOTAL_TASKS*100}%"></span></div><div class="progress-caption"><span>${done} of ${TOTAL_TASKS} sessions complete</span><span>${days>0?`${days} days to go`:days===0?'Exam day':'Exam date passed'}</span></div></div><div class="section-title"><h2>Today’s focus <span class="count">${tasks.length+dayTodos(today).length}</span></h2>${addTodoButton(today)}</div><div class="task-list">${tasks.length||dayTodos(today).length?tasks.map(sessionCard).join('')+personalTodos(today):`<div class="empty"><strong>${today>END?'Your study journey':'Space to recharge.'}</strong>${today>END?'Your completed sessions are in All topics.':'Nothing scheduled today. Explore your calendar to see what’s next.'}<br><button class="text-button" data-page="calendar">Open your calendar →</button></div>`}</div>${backlog.length?`<div class="section-title"><h2>Needs a place <span class="count">${backlog.length}</span></h2></div><p class="subtle">These sessions could not fit. Adjust your rhythm or open a session to choose a day.</p><div class="task-list">${backlog.map(sessionCard).join('')}</div>`:''}<p class="subtle spacer">${today<REV_START?'Watch the video, then mark it complete.':'Recall first, then check your notes.'}</p></section><aside class="right-column"><div class="week-card"><div class="section-title"><h2>Your next 7 days</h2><button class="text-button" data-page="calendar">View all ↗</button></div><div class="week-bars">${range(today,addDays(today,6)).map(d=>{const n=dayTasks(d).length;return `<button class="bar-day ${d===today?'is-today':''}" data-day="${d}" aria-label="${longDate(d)}, ${n} sessions"><small>${n}</small><span class="bar" style="--height:${Math.min(n*14+5,76)}px"></span><span>${fmt(d,{weekday:'narrow'})}</span></button>`;}).join('')}</div><div class="week-key"><i></i> Sessions planned · weighted to your rhythm</div></div></aside></div>`;}
const WEIGHT_LABELS={off:'Off',light:'Light',normal:'Normal',heavy:'Heavy'};
function weightPicker(name,current,ariaLabel,withDefault=false){const opts=[...(withDefault?[['default','Default']]:[]),...Object.keys(WEIGHTS).map(w=>[w,WEIGHT_LABELS[w]])];return `<div class="weight-picker" role="radiogroup" aria-label="${esc(ariaLabel)}">${opts.map(([value,label])=>`<label class="weight-option"><input type="radio" name="${name}" value="${value}" ${value===current?'checked':''}>${label}</label>`).join('')}</div>`;}
function calendarPage(){const first=month+'-01',offset=(dateObj(first).getDay()+6)%7,start=addDays(first,-offset);return header('Calendar','Tap a day to see its sessions.','YOUR CALENDAR')+warnings()+`<div class="calendar-layout"><section class="calendar-card"><div class="calendar-toolbar"><h2>${fmt(first,{month:'long',year:'numeric'})}</h2><div class="actions"><button class="icon-button" data-month="-1" aria-label="Previous month" ${month<='2026-09'?'disabled':''}>‹</button><button class="text-button" data-day="${today<START?START:today>END?END:today}">Today</button><button class="icon-button" data-month="1" aria-label="Next month" ${month>='2026-10'?'disabled':''}>›</button></div></div><div class="weekdays">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d=>`<span>${d}</span>`).join('')}</div><div class="month-grid">${range(start,addDays(start,Math.ceil((offset+new Date(dateObj(first).getFullYear(),dateObj(first).getMonth()+1,0).getDate())/7)*7-1)).map(d=>{const tasks=dayTasks(d),active=d>=START&&d<=EXAM;return `<button class="day ${d.slice(0,7)!==month?'outside':''} ${tasks.length?'has-tasks':''} ${selected===d?'selected':''} ${d===today?'is-today':''} ${d===EXAM?'exam':''}" data-day="${d}" ${!active?'disabled':''} aria-pressed="${selected===d}" aria-label="${longDate(d)}, ${tasks.length} sessions${d===EXAM?', exam day':''}"><span class="day-number">${dateObj(d).getDate()}</span>${active&&d!==EXAM?`<span class="day-weight">${{heavy:'＋',light:'−',off:'·',normal:''}[weightName(state,d)]}</span>`:''}<span class="day-dots">${tasks.slice(0,6).map(t=>`<i class="${t.stage?'rev':''} ${t.doneAt?'completed':''}"></i>`).join('')}</span><span class="day-load">${d===EXAM?'EXAM':tasks.length?`${tasks.filter(t=>t.doneAt).length}/${tasks.length} done`:active?'Free':''}</span></button>`;}).join('')}</div><div class="calendar-legend"><span><i class="dot"></i> First pass</span><span><i class="dot revision"></i> Revision</span><span class="weight-legend">＋ Heavy &nbsp; − Light</span></div><p class="subtle spacer">First pass: Sep 18–26 · Revision: Sep 27–Oct 14. <span class="desktop-only">Drag a session onto a day to move it.</span></p></section><section class="day-detail"><div class="eyebrow">${fmt(selected,{weekday:'long'}).toUpperCase()}</div><h2 class="selected-day-heading">${fmt(selected,{month:'long',day:'numeric'})}</h2>${selected<EXAM?`<div class="select-label">This day’s workload</div>${weightPicker('day-weight',state.overrides[selected]||'default','Selected day workload',true)}`:'<p class="subtle">Exam day.</p>'}<div class="day-list-actions">${addTodoButton(selected)}</div><div class="task-list">${dayTasks(selected).length||dayTodos(selected).length?dayTasks(selected).map(sessionCard).join('')+personalTodos(selected):'<div class="empty"><strong>A little breathing room.</strong>No sessions scheduled.</div>'}</div>${selected<EXAM?'<p class="subtle spacer">Changing the workload redistributes unfinished, unpinned sessions. Completed sessions stay put.</p>':''}</section></div>`;}
function topicsPage(){const doneCount=i=>state.tasks.filter(t=>t.stage===i&&t.doneAt).length;return header('All topics',`${TOPICS.length} videos, two reviews each.`,'THE BIG PICTURE')+warnings()+`<div class="stat-row">${STAGES.map((s,i)=>`<div class="stat"><strong>${doneCount(i)}<span style="font-family:inherit;font-size:20px"> / ${TOPICS.length}</span></strong><span>${s==='First pass'?'Videos watched':s+' complete'}</span><div class="stat-track"><span style="width:${doneCount(i)/TOPICS.length*100}%"></span></div></div>`).join('')}</div>${['Eye','ENT'].map(subject=>`<section class="topic-group"><h2>${subject} <span class="count">${TOPICS.filter(p=>p.subject===subject).length}</span></h2>${TOPICS.filter(p=>p.subject===subject).map(p=>{const stages=[0,1,2].map(i=>getTask(`${p.id}:${i}`)),complete=stages.filter(t=>t.doneAt).length;return `<div class="topic-row"><span class="topic-number">${String(p.number).padStart(2,'0')}</span><div class="topic-info"><h3>${esc(p.title)}</h3><span class="topic-progress ${complete===3?'done':''}">${complete}/3</span></div><div class="topic-stages">${stages.map((t,i)=>`<button class="stage-chip ${t.doneAt?'completed':''}" data-session="${t.id}" aria-label="${esc(p.title)} ${STAGES[i]} ${t.doneAt?'complete':t.date?fmt(t.date):'unscheduled'}">${t.doneAt?'✓ ':''}${['Watch','R1','R2'][i]} · ${t.date?fmt(t.date):'Unplaced'}</button>`).join('')}</div></div>`;}).join('')}</section>`).join('')}`;}
function settingsPage(){return header('Settings','Your rhythm, backups, and preferences.','SETTINGS')+warnings()+`<div class="settings-grid"><section class="panel"><h2>A week that works for you</h2><p>Light days carry half the normal load; heavy days carry twice as much. Off days get no automatic sessions. Each session counts equally because video lengths aren’t supplied.</p><form id="rhythm-form">${[1,2,3,4,5,6,0].map(d=>{const day=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][d];return `<div class="rhythm-row"><span class="rhythm-day">${day}</span>${weightPicker('weekday-'+d,state.weekly[d],`${day} workload`)}</div>`;}).join('')}<label class="field">First study day<input name="start" type="date" value="${state.start}" min="2026-09-18" max="2026-09-26" required></label><button class="button" type="submit">Save rhythm & rebalance</button><p>Manual moves stay fixed unless they conflict with the review order. Change individual days in Calendar.</p></form></section><div class="settings-stack"><section class="panel"><h2>How your plan works</h2><ol class="rule-list"><li>All ${TOPICS.length} first viewings are planned by the end of September 26.</li><li>Revision begins September 27. First recall follows watching; the second review aims for about a week later, with a minimum 3-day gap.</li><li>Both reviews are planned by October 14. Missed work spreads over the remaining available days when you reopen the app.</li><li>If dates or off days make that impossible, sessions stay visible under “Needs a place”.</li></ol><p>Spaced repetition inspired. For revision, try recalling the topic before checking your notes.</p></section><section class="panel"><h2>Your plan, on this device</h2><p>No account. No cloud sync. Export a backup to keep progress safe or move it to another device.</p><div class="actions"><button class="button secondary" data-export>Export backup</button><button class="button secondary" data-import>Restore backup</button><input id="import-file" type="file" accept="application/json,.json" hidden></div><div class="actions spacer"><button class="text-button" data-undo>Undo last change</button><button class="text-button" data-rebalance>Release moves & rebalance</button></div><p class="spacer">Clearing progress only affects this app; it does not touch other sites' data.</p><div class="actions"><button class="button danger" data-clear>Clear all progress</button></div></section></div></div>`;}
function render(){const home=collectionStatus(state,today);petNav.hidden=!home.unlocked;navigation.classList.toggle('has-companions',home.unlocked);if(page==='companions'&&!home.unlocked){page='today';history.replaceState(null,'','#today');}const previousFill=captureRewardFill(main);document.querySelectorAll('nav [data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});updateNavHighlight();main.innerHTML=({today:todayPage,calendar:calendarPage,topics:topicsPage,companions:()=>warnings()+companionsPage(state,today),settings:settingsPage})[page]();animateRewardFill(main,previousFill);updateStorageBadge();companionIntro.update(home,state.collection.introSeen);}
function openSession(id){activeId=id;const t=getTask(id),p=topicOf(t);dialog.innerHTML=`<button class="dialog-close" data-close aria-label="Close session">×</button><span class="subject ${p.subject.toLowerCase()}">${p.subject.toUpperCase()} · ${STAGES[t.stage].toUpperCase()}</span><h2>${esc(p.title)}</h2><p>${t.doneAt?`Completed ${fmt(t.doneAt)}.`:`Scheduled ${t.date?longDate(t.date):'when a study day becomes available'}.`} ${t.stage?'Try recalling the key points before opening your notes.':'Watch the lecture, then tick it off.'}</p><button class="button" data-modal-toggle="${id}">${t.doneAt?'Undo completion':'Mark complete today'}</button>${!t.doneAt?`<form id="move-form"><label class="field">Move to a day<input type="date" id="move-date" name="date" min="${today>state.start?today:state.start}" max="${t.stage===0&&today<=LEARN_END?LEARN_END:END}" value="${t.date||today}" required></label><label class="field">Move or swap<select id="swap-with" name="swap" aria-label="Move or swap"><option value="">Move this session only</option></select></label><p class="badge">Moving shifts this session; swapping exchanges two dates. Later reviews adjust if needed. Manual choices stay pinned when rebalancing, including on off days.</p><div class="dialog-error" id="move-error" role="alert"></div><button class="button secondary" type="submit">Save schedule</button></form>`:''}<p class="badge spacer">${[0,1,2].map(i=>{const x=getTask(`${p.id}:${i}`);return `${STAGES[i]}: ${x.date?fmt(x.date):'unplaced'}${x.doneAt?' ✓':''}`;}).join(' &nbsp; · &nbsp; ')}</p>`;if(!t.doneAt)fillSwaps();if(!dialog.open)dialog.showModal();}
function fillSwaps(){const d=document.querySelector('#move-date').value,options=state.tasks.filter(t=>!t.doneAt&&t.id!==activeId&&t.date===d);document.querySelector('#swap-with').innerHTML='<option value="">Move this session only</option>'+options.map(t=>`<option value="${t.id}">Swap with ${esc(topicOf(t).title)} · ${STAGES[t.stage]}</option>`).join('');}
document.addEventListener('click',e=>{const b=e.target.closest('button, a.brand');if(!b)return;if(b.matches('a.brand')){e.preventDefault();navigate('today');}else if(b.dataset.page)navigate(b.dataset.page);else if(b.dataset.addTodo)openTodo(b.dataset.addTodo);else if(b.dataset.editTodo)openTodo(null,b.dataset.editTodo);else if(b.dataset.todoToggle)mutate(()=>toggleTodo(state,b.dataset.todoToggle));else if(b.dataset.deleteTodo){if(mutate(()=>deleteTodo(state,b.dataset.deleteTodo),'To-do deleted. You can undo this in Settings.'))dialog.close();}else if(b.dataset.todoColour){dialog.querySelector('[name=colour]').value=b.dataset.todoColour;dialog.querySelectorAll('[data-todo-colour]').forEach(x=>x.setAttribute('aria-pressed',x===b));}else if(b.hasAttribute('data-bounce'))bounceCompanion(b);else if(b.hasAttribute('data-finish-day')){const wasUnlocked=collectionStatus(state,today).unlocked;if(mutate(()=>finishDailyReward(state,today))){const h=collectionStatus(state,today);toast(!wasUnlocked&&h.unlocked?'Pip hatched! Your Companions tab is ready.':h.unlocked?'Day finished. One care reward saved.':'A little warmer. Pip’s egg is closer to hatching.');}if(dailyRewardStatus(state,today).finished){const art=document.querySelector('.companion-card [data-bounce]');if(art)celebrateCompanion(art);}}else if(b.dataset.toggle)mutate(()=>toggleTask(state,b.dataset.toggle,today),getTask(b.dataset.toggle).doneAt?'Completion undone.':'One step closer. Session complete.');else if(b.dataset.session)openSession(b.dataset.session);else if(b.dataset.modalToggle){if(mutate(()=>toggleTask(state,b.dataset.modalToggle,today),'Progress updated.'))dialog.close();}else if(b.hasAttribute('data-close'))b.closest('dialog').close();else if(b.dataset.day){selected=b.dataset.day;month=selected.slice(0,7);navigate('calendar');if(matchMedia('(max-width:600px)').matches)requestAnimationFrame(()=>document.querySelector('.day-detail').scrollIntoView({block:'start',behavior:'smooth'}));}else if(b.dataset.month){const d=dateObj(month+'-01');d.setMonth(d.getMonth()+Number(b.dataset.month));month=iso(d).slice(0,7);render();}else if(b.hasAttribute('data-export')){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`little-by-little-${today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported.');}else if(b.hasAttribute('data-import'))document.querySelector('#import-file').click();else if(b.hasAttribute('data-undo')){try{const raw=storage.getItem(UNDO);if(!raw)throw Error('No recent change to undo.');const previous=validateState(JSON.parse(raw));const current=JSON.stringify(state),introSeen=state.collection?.introSeen;state=previous;rollover(state,today);if(introSeen)state.collection.introSeen=true;storage.setItem(UNDO,current);save();render();toast('Last change undone.');}catch(e){toast(e.message);}}else if(b.hasAttribute('data-rebalance'))mutate(()=>replan(state,today,{releasePins:true}),'Manual moves released. Unfinished sessions rebalanced.');else if(b.hasAttribute('data-clear')){if(confirm('Clear all local progress for Little by little? This cannot be undone.')){try{storage.removeItem(KEY);storage.removeItem(UNDO);}catch{}storageError='';state=createState(today);save();render();toast('Progress cleared.');}}});
document.addEventListener('change',async e=>{if(e.target.name==='colour'&&e.target.closest('#todo-form'))dialog.querySelectorAll('[data-todo-colour]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.todoColour===e.target.value));else if(e.target.name==='day-weight')mutate(()=>{if(e.target.value==='default')delete state.overrides[selected];else state.overrides[selected]=e.target.value;replan(state,today);},'Day updated. Your plan has been rebalanced.');else if(e.target.id==='move-date')fillSwaps();else if(e.target.id==='import-file'){const file=e.target.files?.[0];if(!file)return;try{if(file.size>1000000)throw Error('Choose a Little by little JSON backup under 1 MB.');const restored=validateState(JSON.parse(await file.text()));snapshot();state=restored;storageError='';replan(state,today);save();render();toast('Backup restored. Use Undo last change to reverse.');}catch(err){toast('Could not restore: '+err.message);}}});
document.addEventListener('submit',e=>{if(e.target.id==='todo-form'){e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim();if(!title){e.target.elements.title.setCustomValidity('Give your to-do a name.');e.target.elements.title.reportValidity();return;}if(mutate(()=>saveTodo(state,{id:e.target.dataset.id||undefined,title,date:f.get('date'),colour:f.get('colour')}),'To-do saved.'))dialog.close();}else if(e.target.id==='rhythm-form'){e.preventDefault();const f=new FormData(e.target);mutate(()=>{state.weekly=Array.from({length:7},(_,i)=>f.get('weekday-'+i));state.start=f.get('start');replan(state,today);},'Your rhythm is saved. The plan is balanced.');}else if(e.target.id==='move-form'){e.preventDefault();const f=new FormData(e.target),before=structuredClone(state);try{moveTask(state,activeId,f.get('date'),today,f.get('swap')||null);try{storage.setItem(UNDO,JSON.stringify(before));}catch{}save();render();dialog.close();toast(f.get('swap')?'Sessions swapped.':'Session moved. Later reviews adjusted if needed.');}catch(err){state=before;document.querySelector('#move-error').textContent=err.message;}}});
document.addEventListener('input',e=>{if(e.target.name==='title'&&e.target.closest('#todo-form'))e.target.setCustomValidity('');});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-task]');if(card){e.dataTransfer.setData('text/plain',card.dataset.task);e.dataTransfer.effectAllowed='move';}});
document.addEventListener('dragover',e=>{if(e.target.closest('.day:not(:disabled)'))e.preventDefault();});
document.addEventListener('drop',e=>{const d=e.target.closest('.day:not(:disabled)');if(d){e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(getTask(id))mutate(()=>moveTask(state,id,d.dataset.day,today),'Session moved.');}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(['today','calendar','topics','companions','settings'].includes(p)){companionIntro.dismiss();page=p;render();}});
function checkDay(){if(demo)return;const next=localToday();if(next!==today){today=next;rollover(state,today);save();render();}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkDay();});setInterval(checkDay,60000);
window.addEventListener('storage',e=>{if(!demo&&e.key===KEY&&e.newValue){try{state=validateState(JSON.parse(e.newValue));rollover(state,today);render();toast('Progress updated from another tab.');}catch{}}});
const companionIntro=createCompanionIntro({nav:petNav,onSeen:()=>{state.collection.introSeen=true;save();},navigate});
save();render();
if('serviceWorker' in navigator&&window.isSecureContext)navigator.serviceWorker.register('./sw.js').catch(()=>{});
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'read_study_plan',description:'Read the local Eye and ENT study schedule and completion status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({today,tasks:state.tasks.map(t=>({id:t.id,title:topicOf(t).title,stage:STAGES[t.stage],date:t.date,completed:!!t.doneAt})),notices:state.notices})});
 register({name:'move_study_session',description:'Move an unfinished session to a date, adjusting dependent reviews. Optionally swap with a session on that date.',inputSchema:{type:'object',properties:{id:{type:'string'},date:{type:'string'},swapId:{type:'string'}},required:['id','date'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.id!=='string'||typeof input.date!=='string'||(input.swapId!==undefined&&typeof input.swapId!=='string'))throw Error('Provide a session id and YYYY-MM-DD date.');const before=structuredClone(state);moveTask(state,input.id,input.date,today,input.swapId||null);try{storage.setItem(UNDO,JSON.stringify(before));}catch{}save();render();return {id:input.id,date:getTask(input.id).date};}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

function careGoalCard(){
 if(!dailyRewardStatus(state,today).careMode)return '';
 const goal=state.collection.careDays[today];
 return `<section class="panel daily-care-panel"><div class="section-title"><h2>A little every day</h2><button class="text-button" data-care-goal ${goal?.done?'disabled':''}>${goal?'Edit goal':'Set a goal'}</button></div><p class="subtle">Keep your companions growing after the exam. Complete one daily goal, then Finish the day for a care reward.</p>${goal?`<article class="task-card ${goal.done?'done':''}"><button class="check" data-care-toggle aria-pressed="${goal.done}" aria-label="${goal.done?'Undo':'Complete'} daily care goal">${goal.done?'✓':''}</button><div class="task-copy"><span class="subject eye">DAILY GOAL</span><h3>${esc(goal.goal)}</h3></div></article>`:'<p class="subtle">Pick something small and meaningful: read a page, practise a skill, or take a mindful walk.</p>'}</section>`;
}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.choosePet)mutate(()=>chooseCompanion(state,b.dataset.choosePet,today),'Companion selected.');
 else if(b.dataset.adoptEgg)mutate(()=>adoptEgg(state,b.dataset.adoptEgg,today),'Minty’s egg has a home. Warm it with four care rewards.');
 else if(b.hasAttribute('data-spend-care')){
  const before=collectionStatus(state,today).selected;
  if(mutate(()=>spendCare(state,today))){
   const after=collectionStatus(state,today).selected;
   toast(!before.hatched&&after.hatched?`${after.name} hatched! Welcome to the world.`:after.level>before.level?`${after.name} reached level ${after.level}!`:after.hatched?`${after.name} enjoyed that. One reward used.`:'A little warmer. One reward used.');
   const art=main.querySelector('.companion-card [data-bounce]');if(art)celebrateCompanion(art);
  }
 }else if(b.hasAttribute('data-care-toggle'))mutate(()=>toggleCareGoal(state,today));
 else if(b.hasAttribute('data-care-goal')){
  dialog.innerHTML=`<button class="dialog-close" data-close aria-label="Close">×</button><div class="eyebrow">A LITTLE EVERY DAY</div><h2>Your daily goal</h2><form id="care-goal-form"><label class="field">One thing for today<input name="goal" value="${esc(state.collection.careDays[today]?.goal||'')}" maxlength="200" required placeholder="Read for ten minutes" autofocus></label><p>Completing this goal unlocks today’s care reward. Your personal to-dos remain separate.</p><button class="button" type="submit">Save goal</button></form>`;dialog.showModal();
 }
});
document.addEventListener('submit',e=>{if(e.target.id==='care-goal-form'){e.preventDefault();if(mutate(()=>saveCareGoal(state,today,new FormData(e.target).get('goal')),'Daily goal saved.'))dialog.close();}});
